required_pg <- c("PGDATABASE","PGHOST","PGPORT","PGUSER","PGPASSWORD")
pg <- setNames(lapply(required_pg,function(k) Sys.getenv(k,unset=NA_character_)),required_pg)
if(any(vapply(pg,function(v) length(v)!=1L||is.na(v),logical(1)))) stop("IDENTITY_DELETE_LOCK_REQUIRES_ALL_FIVE_PG_VARIABLES",call.=FALSE)
if(!grepl("^daa1939_c3_identity_task2_",pg$PGDATABASE)) stop("IDENTITY_DELETE_LOCK_REQUIRES_DISPOSABLE_DATABASE",call.=FALSE)
connect<-function()DBI::dbConnect(RPostgres::Postgres(),dbname=pg$PGDATABASE,host=pg$PGHOST,port=pg$PGPORT,user=pg$PGUSER,password=pg$PGPASSWORD)
q<-function(c,s,p=list())if(length(p))DBI::dbGetQuery(c,s,params=p)else DBI::dbGetQuery(c,s)
x<-function(c,s,p=list())if(length(p))DBI::dbExecute(c,s,params=p)else DBI::dbExecute(c,s)
actor<-"19390000-0000-4000-8000-000000000096"; controller<-connect(); blocker<-connect()
section<-Sys.getenv("C3_IDENTITY_DELETE_LOCK_SECTION","all")
on.exit(try(DBI::dbDisconnect(controller),silent=TRUE),add=TRUE);on.exit(try(DBI::dbDisconnect(blocker),silent=TRUE),add=TRUE)
x(controller,"CREATE EXTENSION IF NOT EXISTS dblink WITH SCHEMA extensions")
x(controller,"INSERT INTO auth.users(id,email) VALUES($1,'identity-delete-lock@test.invalid') ON CONFLICT DO NOTHING",list(actor))
x(controller,"INSERT INTO profiles(id,email,rolle) VALUES($1,'identity-delete-lock@test.invalid','redaktion') ON CONFLICT(id) DO UPDATE SET rolle='redaktion'",list(actor))
set_actor<-function(c)invisible(q(c,"SELECT set_config('request.jwt.claim.sub',$1,false)",list(actor)));set_actor(controller);set_actor(blocker)
cleanup<-function(){try(x(controller,"DROP TRIGGER IF EXISTS trg_c3_identity_undo_pause ON change_set"),silent=TRUE);try(x(controller,"DROP FUNCTION IF EXISTS private.c3_identity_undo_pause()"),silent=TRUE);rels<-try(q(controller,"SELECT id::text id FROM relation WHERE (subjekt_id BETWEEN -1939516199 AND -1939516100) OR (objekt_id BETWEEN -1939516199 AND -1939516100)"),silent=TRUE);if(!inherits(rels,"try-error")&&nrow(rels))for(rid in rels$id){try(q(controller,"SELECT set_config('app.change_set_id','',false)"),silent=TRUE);try(q(controller,"SELECT red_slet_relation($1::bigint)",list(rid)),silent=TRUE)};try(x(controller,"DELETE FROM change_event WHERE change_set_id IN (SELECT id FROM change_set WHERE actor_id=$1)",list(actor)),silent=TRUE);try(x(controller,"DELETE FROM change_set WHERE actor_id=$1",list(actor)),silent=TRUE);try(x(controller,"DELETE FROM relation WHERE (subjekt_id BETWEEN -1939516199 AND -1939516100) OR (objekt_id BETWEEN -1939516199 AND -1939516100)"),silent=TRUE);try(x(controller,"DELETE FROM media WHERE id BETWEEN -1939516199 AND -1939516100"),silent=TRUE);try(x(controller,"DELETE FROM person WHERE id BETWEEN -1939516199 AND -1939516100"),silent=TRUE)}
cleanup();on.exit(cleanup(),add=TRUE)
conninfo<-paste(paste0("dbname=",pg$PGDATABASE),paste0("host=",pg$PGHOST),paste0("port=",pg$PGPORT),paste0("user=",pg$PGUSER),paste0("password=",pg$PGPASSWORD))
remote<-c("identity_lock_delete","identity_lock_writer");for(n in remote)q(controller,"SELECT extensions.dblink_connect($1,$2)",list(n,conninfo))
on.exit(for(n in remote){try(q(controller,"SELECT extensions.dblink_exec($1,'ROLLBACK')",list(n)),silent=TRUE);try(q(controller,"SELECT extensions.dblink_disconnect($1)",list(n)),silent=TRUE)},add=TRUE)
rexec<-function(n,s)q(controller,"SELECT extensions.dblink_exec($1,$2)",list(n,s));send<-function(n,s){if(q(controller,"SELECT extensions.dblink_send_query($1,$2) sent",list(n,s))$sent[[1L]]!=1L)stop("IDENTITY_DELETE_LOCK_SEND_FAILED",call.=FALSE)}
begin_remote<-function(n,pause=FALSE){rexec(n,"ROLLBACK");rexec(n,"BEGIN");rexec(n,paste0("SET LOCAL request.jwt.claim.sub='",actor,"'"));rexec(n,"SET LOCAL statement_timeout='7s'");rexec(n,"SET LOCAL app.change_set_id TO ''");if(pause)rexec(n,"SET LOCAL app.c3_identity_undo_pause='1'")}
pid<-setNames(vapply(remote,function(n)q(controller,"SELECT * FROM extensions.dblink($1,'SELECT pg_backend_pid()') AS t(pid integer)",list(n))$pid[[1L]],integer(1)),remote)
wait_lock<-function(n,tag){deadline<-Sys.time()+5;repeat{s<-q(controller,"SELECT wait_event_type,wait_event FROM pg_stat_activity WHERE pid=$1",list(pid[[n]]));if(nrow(s)==1L&&identical(s$wait_event_type[[1L]],"Lock"))return();if(Sys.time()>=deadline)stop(paste0("IDENTITY_DELETE_LOCK_NOT_BLOCKED_",tag),call.=FALSE);Sys.sleep(.01)}}
finish<-function(n){deadline<-Sys.time()+9;repeat{if(q(controller,"SELECT extensions.dblink_is_busy($1) busy",list(n))$busy[[1L]]==0L)break;if(Sys.time()>=deadline)stop(paste0("IDENTITY_DELETE_LOCK_TIMEOUT_",n),call.=FALSE);Sys.sleep(.01)};r<-suppressWarnings(try(q(controller,"SELECT * FROM extensions.dblink_get_result($1,true) AS t(value text)",list(n)),silent=TRUE));suppressWarnings(try(q(controller,"SELECT * FROM extensions.dblink_get_result($1,true) AS t(value text)",list(n)),silent=TRUE));rexec(n,if(inherits(r,"try-error"))"ROLLBACK" else "COMMIT");r}
assert_no_deadlock<-function(results,tag){if(any(vapply(results,function(r)inherits(r,"try-error")&&grepl("deadlock detected",as.character(r),fixed=TRUE,useBytes=TRUE),logical(1))))stop(paste0("IDENTITY_DELETE_LOCK_DEADLOCK_",tag),call.=FALSE)}
seed_afbildet<-function(person_id,media_id,relation_id){x(controller,"INSERT INTO person(id,levende,koen) VALUES($1,false,'ukendt') ON CONFLICT DO NOTHING",list(person_id));x(controller,"INSERT INTO media(id,slags,titel) VALUES($1,'foto','lock fixture') ON CONFLICT DO NOTHING",list(media_id));x(controller,"INSERT INTO relation(id,subjekt_type,subjekt_id,objekt_type,objekt_id,rolle) VALUES($1,'person',$2,'media',$3,'afbildet')",list(relation_id,person_id,media_id))}
run_portrait_delete<-function(first,person_id,media_id,relation_id){seed_afbildet(person_id,media_id,relation_id);DBI::dbBegin(blocker);q(blocker,"SELECT id FROM relation WHERE id=$1 FOR UPDATE",list(relation_id));begin_remote(remote[[1L]]);begin_remote(remote[[2L]]);sql<-list(delete=sprintf("SELECT public.red_slet_relation(%s)::text",relation_id),portrait=sprintf("SELECT public.red_saet_portraet(%s,%s)::text",person_id,media_id));names<-if(first=="delete")remote else rev(remote);send(names[[1L]],sql[[first]]);wait_lock(names[[1L]],paste0("portrait_",first,"_first"));second<-if(first=="delete")"portrait" else "delete";send(names[[2L]],sql[[second]]);wait_lock(names[[2L]],paste0("portrait_",second,"_second"));DBI::dbCommit(blocker);r1<-finish(names[[1L]]);r2<-finish(names[[2L]]);assert_no_deadlock(list(r1,r2),paste0("portrait_",first));if(inherits(r1,"try-error"))stop(paste0("IDENTITY_DELETE_LOCK_FIRST_OPERATION_FAILED_portrait_",first,": ",r1),call.=FALSE);state<-q(controller,"SELECT rolle,(kvalifikator->>'primaer')::boolean primaer FROM relation WHERE id=$1",list(relation_id));if(first=="delete"&&nrow(state)!=0L)stop("IDENTITY_DELETE_LOCK_DELETE_OUTCOME_DRIFT",call.=FALSE);if(first=="portrait"&&(nrow(state)!=1L||!isTRUE(state$primaer[[1L]])))stop("IDENTITY_DELETE_LOCK_PORTRAIT_OUTCOME_DRIFT",call.=FALSE)}
if(section %in% c("all","portrait")){run_portrait_delete("delete",-1939516101,-1939516111,-1939516121);run_portrait_delete("portrait",-1939516102,-1939516112,-1939516122)}

if(section %in% c("all","undo")){x(controller,"CREATE FUNCTION private.c3_identity_undo_pause() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN IF current_setting('app.c3_identity_undo_pause',true)='1' AND NEW.operation='fortryd' THEN PERFORM pg_advisory_xact_lock(1939516,1); END IF; RETURN NEW; END $$");x(controller,"CREATE TRIGGER trg_c3_identity_undo_pause AFTER INSERT ON change_set FOR EACH ROW EXECUTE FUNCTION private.c3_identity_undo_pause()")}
seed_undo<-function(a,b){for(id in c(a,b))x(controller,"INSERT INTO person(id,levende,koen) VALUES($1,false,'ukendt') ON CONFLICT DO NOTHING",list(id));q(controller,"SELECT set_config('app.change_set_id','',false)");rid<-q(controller,"SELECT red_relation('person',$1,'person',$2,'associeret') id",list(a,b))$id[[1L]];cs<-q(controller,"SELECT change_set_id id FROM change_event WHERE tabel='relation' AND op='INSERT' AND (row_pk->>'id')::bigint=$1 ORDER BY id DESC LIMIT 1",list(rid))$id[[1L]];q(controller,"SELECT set_config('app.change_set_id','',false)");DBI::dbBegin(controller);q(controller,"SELECT private.prelock_identity_relation_update(to_jsonb(r),to_jsonb(r)||jsonb_build_object('rolle','ikke_samme_som')) FROM relation r WHERE id=$1",list(rid));x(controller,"UPDATE relation SET rolle='ikke_samme_som' WHERE id=$1",list(rid));DBI::dbCommit(controller);list(rid=rid,cs=cs)}
seed_writer_people<-function(a,b){for(id in c(a,b))x(controller,"INSERT INTO person(id,levende,koen) VALUES($1,false,'ukendt') ON CONFLICT DO NOTHING",list(id))}
run_undo_first<-function(){u<-seed_undo(-1939516131,-1939516132);seed_writer_people(-1939516133,-1939516134);q(blocker,"SELECT pg_advisory_lock(1939516,1)");begin_remote(remote[[1L]],TRUE);send(remote[[1L]],sprintf("SELECT red_fortryd_change_set(%s,true)::text",u$cs));wait_lock(remote[[1L]],"undo_first_pause");begin_remote(remote[[2L]]);send(remote[[2L]],"SELECT red_samme_som(-1939516133,-1939516134)::text");wait_lock(remote[[2L]],"undo_first_writer");q(blocker,"SELECT pg_advisory_unlock(1939516,1)");ru<-finish(remote[[1L]]);rw<-finish(remote[[2L]]);assert_no_deadlock(list(ru,rw),"undo_first");if(inherits(ru,"try-error")||inherits(rw,"try-error"))stop(paste0("IDENTITY_DELETE_LOCK_UNDO_FIRST_FAILED: ",ru," / ",rw),call.=FALSE);if(q(controller,"SELECT EXISTS(SELECT 1 FROM relation WHERE id=$1) value",list(u$rid))$value[[1L]])stop("IDENTITY_DELETE_LOCK_UNDO_FIRST_STALE_SUCCESS",call.=FALSE);if(q(controller,"SELECT count(*)::integer n FROM relation WHERE rolle='samme_som' AND subjekt_id=-1939516133 AND objekt_id=-1939516134")$n[[1L]]!=1L)stop("IDENTITY_DELETE_LOCK_UNDO_FIRST_WRITER_LOST",call.=FALSE)}
run_writer_first<-function(){u<-seed_undo(-1939516141,-1939516142);seed_writer_people(-1939516143,-1939516144);DBI::dbBegin(blocker);q(blocker,"SELECT id FROM person WHERE id=-1939516143 FOR UPDATE");begin_remote(remote[[2L]]);send(remote[[2L]],"SELECT red_samme_som(-1939516143,-1939516144)::text");wait_lock(remote[[2L]],"writer_first_person");begin_remote(remote[[1L]]);send(remote[[1L]],sprintf("SELECT red_fortryd_change_set(%s,true)::text",u$cs));wait_lock(remote[[1L]],"writer_first_undo");DBI::dbCommit(blocker);rw<-finish(remote[[2L]]);ru<-finish(remote[[1L]]);assert_no_deadlock(list(rw,ru),"writer_first");if(inherits(ru,"try-error")||inherits(rw,"try-error"))stop(paste0("IDENTITY_DELETE_LOCK_WRITER_FIRST_FAILED: ",rw," / ",ru),call.=FALSE);if(q(controller,"SELECT EXISTS(SELECT 1 FROM relation WHERE id=$1) value",list(u$rid))$value[[1L]])stop("IDENTITY_DELETE_LOCK_WRITER_FIRST_STALE_SUCCESS",call.=FALSE);if(q(controller,"SELECT count(*)::integer n FROM relation WHERE rolle='samme_som' AND subjekt_id=-1939516143 AND objekt_id=-1939516144")$n[[1L]]!=1L)stop("IDENTITY_DELETE_LOCK_WRITER_FIRST_WRITER_LOST",call.=FALSE)}
if(section %in% c("all","undo")){run_undo_first();run_writer_first()}
if(section=="all"){seed_writer_people(-1939516151,-1939516152);rid<-q(controller,"SELECT red_samme_som(-1939516151,-1939516152) id")$id[[1L]];begin_remote(remote[[1L]]);rexec(remote[[1L]],"DO $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext('samme_som_mutation')); PERFORM private.guard_identity_mutation_snapshot(); END $$");rexec(remote[[1L]],"ROLLBACK");begin_remote(remote[[1L]]);send(remote[[1L]],sprintf("SELECT _delete_relation_evidence(%s)::text",rid));raw<-finish(remote[[1L]]);if(!inherits(raw,"try-error")||!grepl("IDENTITY_RELATION_DELETE_RETRY_REQUIRED",as.character(raw),fixed=TRUE,useBytes=TRUE))stop("IDENTITY_DELETE_RAW_HELPER_DID_NOT_FAIL_CLOSED",call.=FALSE);if(!q(controller,"SELECT EXISTS(SELECT 1 FROM relation WHERE id=$1) value",list(rid))$value[[1L]])stop("IDENTITY_DELETE_RAW_HELPER_MUTATED",call.=FALSE)}
